def clean(df):
    df = df.copy()
    # remove exact duplicate rows
    df = df.drop_duplicates()
    # body_mass_g is stored as text with commas e.g. "3,075" -> numeric
    if "body_mass_g" in df.columns:
        df["body_mass_g"] = pd.to_numeric(df["body_mass_g"].astype(str).str.replace(",", "", regex=False), errors="coerce")
    # normalize sex case variants MALE/FEMALE -> male/female, keep NaN as unknown
    if "sex" in df.columns:
        df["sex"] = df["sex"].astype(object).where(df["sex"].isna(), df["sex"].astype(str).str.strip().str.lower())
    # flipper_length_mm negatives are data entry errors (-200 -> 200)
    if "flipper_length_mm" in df.columns:
        df["flipper_length_mm"] = pd.to_numeric(df["flipper_length_mm"], errors="coerce").abs()
    return df

def answer(df):
    df = df.copy()
    # ensure body_mass_g numeric for grouping
    if "body_mass_g" in df.columns:
        df["body_mass_g"] = pd.to_numeric(df["body_mass_g"].astype(str).str.replace(",", "", regex=False), errors="coerce")
    # drop missing group keys
    df = df.dropna(subset=["species"])
    grouped = df.groupby("species")["body_mass_g"].mean()
    return {str(k): float(v) for k, v in grouped.items()}
